using System.Buffers.Binary;
using Compression.Core.Dictionary.QuickLz;
using FileFormat.QuickLz;

namespace Compression.Tests.QuickLz;

[TestFixture]
public sealed class QuickLzTests {
  // Generated by the independent MIT/Apache-2.0 ReSpeak QuickLZ 1.5.0 implementation
  // (quicklz crate 0.3.1), then frozen here as interoperability data. This deliberately
  // contains a level-1 hash-index reference rather than being a stored-only packet.
  private static readonly byte[] OracleRepetitivePacket = Convert.FromHexString(
    "471B0000002C01000030000080414141415055FF50552541414141");

  // Published QuickLZ 1.5.0 documentation example: a long-header compressed packet whose
  // control word describes ten literal tokens carrying bytes 0..9.
  private static readonly byte[] PublishedLiteralPacket = Convert.FromHexString(
    "47170000000A0000000000008000010203040506070809");

  [TestCase(0)]
  [TestCase(1)]
  [TestCase(215)]
  [TestCase(216)]
  [TestCase(256)]
  [TestCase(4096)]
  [TestCase(65536)]
  public void RoundTrip_DeterministicData(int size) {
    var data = Enumerable.Range(0, size).Select(i => (byte)((i * 37 + i / 11) & 0xff)).ToArray();
    var packet = Compress(data);

    Assert.That(Decompress(packet), Is.EqualTo(data));
  }

  [Test]
  public void Decompress_PublishedLiteralVector() {
    Assert.That(Decompress(PublishedLiteralPacket), Is.EqualTo(Enumerable.Range(0, 10).Select(i => (byte)i)));
  }

  [Test]
  public void Decompress_IndependentOracleCompressedVector() {
    Assert.That(Decompress(OracleRepetitivePacket), Is.EqualTo(Enumerable.Repeat((byte)'A', 300)));
  }

  [Test]
  public void Compress_UsesShortHeaderBelow216Bytes() {
    var packet = Compress("TOBEORNOTTOBEORTOBEORNOT"u8.ToArray());

    Assert.That(packet[0] & 0x40, Is.EqualTo(0x40));
    Assert.That(packet[0] & 0x02, Is.Zero);
    Assert.That(packet[1], Is.EqualTo(packet.Length));
    Assert.That(packet[2], Is.EqualTo(24));
  }

  [Test]
  public void Compress_UsesLongHeaderAt216Bytes() {
    var packet = Compress(new byte[216]);

    Assert.That(packet[0] & 0x02, Is.EqualTo(0x02));
    Assert.That(BinaryPrimitives.ReadUInt32LittleEndian(packet.AsSpan(1, 4)), Is.EqualTo((uint)packet.Length));
    Assert.That(BinaryPrimitives.ReadUInt32LittleEndian(packet.AsSpan(5, 4)), Is.EqualTo(216u));
  }

  [Test]
  public void Compress_RepetitiveDataProducesCompressedPacket() {
    var data = Enumerable.Repeat((byte)'A', 10_000).ToArray();
    var packet = Compress(data);

    Assert.That(packet[0] & 0x01, Is.EqualTo(0x01));
    Assert.That(packet.Length, Is.LessThan(data.Length));
  }

  [Test]
  public void CorePayload_RoundTripsAndRejectsUndefinedReference() {
    var data = Enumerable.Range(0, 2048).Select(i => (byte)((i * 13 + i / 5) & 0xff)).ToArray();
    var payload = QuickLzCompressor.Compress(data);
    Assert.That(QuickLzDecompressor.Decompress(payload, data.Length), Is.EqualTo(data));

    // control bit 0 says reference; hash index zero has never been populated.
    var invalid = Convert.FromHexString("010000800300");
    Assert.Throws<InvalidDataException>(() => QuickLzDecompressor.Decompress(invalid, 3));
  }

  [TestCase("00")]
  [TestCase("C4")]
  public void Decompress_RejectsMalformedFlags(string firstByteHex) {
    var packet = Convert.FromHexString(firstByteHex + "0300");
    Assert.Throws<InvalidDataException>(() => Decompress(packet));
  }

  [TestCase("54")]
  [TestCase("48")]
  public void Decompress_RejectsUnsupportedPacketFeatures(string firstByteHex) {
    var packet = Convert.FromHexString(firstByteHex + "0300");
    Assert.Throws<NotSupportedException>(() => Decompress(packet));
  }

  [Test]
  public void Decompress_RejectsTruncatedHeaderAndPayload() {
    Assert.Throws<EndOfStreamException>(() => Decompress([0x46]));
    Assert.Throws<EndOfStreamException>(() => Decompress([0x44, 0x05, 0x02, 0xAA]));
  }

  [Test]
  public void Decompress_RejectsStoredSizeMismatch() {
    Assert.Throws<InvalidDataException>(() => Decompress([0x44, 0x04, 0x02, 0xAA]));
  }

  [Test]
  public void Decompress_ConsumesOnlyDeclaredPacket() {
    var packet = Compress(Enumerable.Repeat((byte)0xA5, 512).ToArray());
    using var input = new MemoryStream([.. packet, 0xDE, 0xAD]);
    using var output = new MemoryStream();

    QuickLzStream.Decompress(input, output);

    Assert.That(input.ReadByte(), Is.EqualTo(0xDE));
    Assert.That(input.ReadByte(), Is.EqualTo(0xAD));
  }

  [Test]
  public void BuildingBlock_RoundTripsAndRejectsMalformedEnvelope() {
    var block = new QuickLzBuildingBlock();
    var source = "QuickLZ building block interoperability"u8.ToArray();
    Assert.That(block.Decompress(block.Compress(source)), Is.EqualTo(source));
    Assert.Throws<InvalidDataException>(() => block.Decompress([0x01, 0x02, 0x03]));
    Assert.Throws<InvalidDataException>(() => block.Decompress([0xFF, 0xFF, 0xFF, 0xFF]));
  }

  private static byte[] Compress(byte[] data) {
    using var input = new MemoryStream(data);
    using var output = new MemoryStream();
    QuickLzStream.Compress(input, output);
    return output.ToArray();
  }

  private static byte[] Decompress(byte[] packet) {
    using var input = new MemoryStream(packet);
    using var output = new MemoryStream();
    QuickLzStream.Decompress(input, output);
    return output.ToArray();
  }
}
